/* ============ 工具函数 ============ */
function $(id){return document.getElementById(id);}
function toast(msg){ const t=$('toast'); t.textContent=msg; t.classList.add('show'); clearTimeout(t._t); t._t=setTimeout(()=>t.classList.remove('show'),2600); }
function splitTerms(str){ return (str||'').split(/[\s,，、;；\n]+/).map(s=>s.trim()).filter(Boolean); }
function escapeHtml(s){ return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function escapeRegex(s){ return String(s).replace(/[.*+?^${}()|[\]\\]/g,'\\$&'); }
function buildRegex(arr){
  if(!arr.length) return /(?!)/;
  return new RegExp('('+arr.map(escapeRegex).join('|')+')');
}

// 分词词典：聚合全部 BASE 类目 + 扩展词典，供 segment() 使用
function buildSegDict() {
  const B = BASE, D = state.dict;
  const s = new Set();
  for (const k of ['brand','competitor','product','geo','company','phone','factory','attribute','audience','question','reputation','promo','price']) {
    (B[k] || []).forEach(t => s.add(t));
  }
  for (const k of ['question','reputation','promo','price','attribute','audience','company','phone','factory']) {
    (D.ext && D.ext[k] || []).forEach(t => s.add(t));
  }
  return s;
}

function buildRegexCache(){
  const D=state.dict;
  state._reCache={
    reQ:buildRegex(BASE.question.concat(D.ext.question)),
    reR:buildRegex(BASE.reputation.concat(D.ext.reputation)),
    reP:buildRegex(BASE.promo.concat(D.ext.promo)),
    rePS:buildRegex(BASE.priceStrong),
    rePW:buildRegex(BASE.priceSoft.concat(D.ext.price)),
    reA:buildRegex(BASE.attribute.concat(D.ext.attribute)),
    reU:buildRegex(BASE.audience.concat(D.ext.audience)),
    reCompany:buildRegex(BASE.company.concat(D.ext.company)),
    rePhone:buildRegex(BASE.phone.concat(D.ext.phone)),
    reFactory:buildRegex(BASE.factory.concat(D.ext.factory))
  };
  // 分词词典缓存（供 classify 接入 segment 使用）
  state._segDict = buildSegDict();
}


/* ============ 双向最大匹配(BMM)分词 ============
   已接入 classify()：用于产品词根召回（见 classify 内 segment 调用）。
   修正点：
   1) 单字回退保留（未登录词按字切开，符合中文分词惯例）；
   2) 双向结果选取由"仅看 token 数"改为"token 数少者优先，相同则单字数少者优先，
      仍相同取 FMM（符合中文左到右阅读习惯）"，避免 BMM 偏置导致的错误切分。 */
function segmentFMM(text, dictSet) {
  const tokens = [];
  let i = 0;
  while (i < text.length) {
    let longest = text[i];
    for (let j = i + 1; j <= text.length; j++) {
      const sub = text.slice(i, j);
      if (dictSet.has(sub) && sub.length > longest.length) longest = sub;
    }
    tokens.push(longest);
    i += longest.length;
  }
  return tokens;
}
function segmentBMM(text, dictSet) {
  const tokens = [];
  let i = text.length;
  while (i > 0) {
    let longest = text[i - 1];
    for (let j = i - 1; j >= 0; j--) {
      const sub = text.slice(j, i);
      if (dictSet.has(sub) && sub.length > longest.length) longest = sub;
    }
    tokens.unshift(longest);
    i -= longest.length;
  }
  return tokens;
}
// 双向最大匹配：token 数少者优先；token 数相同则单字 token 少者优先；仍相同取 FMM
function segment(text, dictSet) {
  const fmm = segmentFMM(text, dictSet);
  const bmm = segmentBMM(text, dictSet);
  const singleCount = t => t.filter(x => x.length === 1).length;
  if (fmm.length !== bmm.length) return fmm.length < bmm.length ? fmm : bmm;
  const sf = singleCount(fmm), sb = singleCount(bmm);
  if (sf !== sb) return sf < sb ? fmm : bmm;
  return fmm;
}

