/* ============ 手动输入关键词 ============ */
function parseManualKeywords(text){
  if(!text) return [];
  // 优先按换行分割；单行时再按逗号/顿号/分号/制表分割
  let parts = text.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);
  if(parts.length<=1){
    parts = text.split(/[,，、;；\t]+/).map(s=>s.trim()).filter(Boolean);
  } else {
    parts = parts.flatMap(line=>{
      const seg=line.split(/[,，、;；\t]+/).map(s=>s.trim()).filter(Boolean);
      return seg.length?seg:[line];
    });
  }
  // 去重（保序）
  const seen=new Set(); const out=[];
  for(const p of parts){ if(!seen.has(p)){ seen.add(p); out.push(p); } }
  return out;
}
function updateKwCount(){
  const n=parseManualKeywords($('kwInput').value).length;
  $('kwCount').textContent=n+' 个关键词';
}
function ingestManualKeywords(){
  const kws=parseManualKeywords($('kwInput').value);
  if(!kws.length){ toast('请先输入至少一个关键词'); return; }
  ingest(kws.map(k=>[k]),'手动输入');
}

/* ============ 事件绑定 ============ */
function bind(){
  const dz=$('dropzone'); const fi=$('fileInput');
  dz.onclick=()=>fi.click();
  fi.onchange=()=>{ if(fi.files[0]) loadFile(fi.files[0]); fi.value=''; };
  ['dragenter','dragover'].forEach(e=>dz.addEventListener(e,ev=>{ev.preventDefault();dz.classList.add('hover');}));
  ['dragleave','drop'].forEach(e=>dz.addEventListener(e,ev=>{ev.preventDefault();dz.classList.remove('hover');}));
  dz.addEventListener('drop',ev=>{ const f=ev.dataTransfer.files[0]; if(f) loadFile(f); });

  $('loadSample').onclick=(e)=>{e.preventDefault(); loadSample();};

  $('kwInput').oninput=updateKwCount;
  $('kwInput').addEventListener('keydown',ev=>{ if((ev.ctrlKey||ev.metaKey)&&ev.key==='Enter'){ ev.preventDefault(); ingestManualKeywords(); } });
  $('btnKwClassify').onclick=ingestManualKeywords;
  $('btnKwClear').onclick=()=>{ $('kwInput').value=''; updateKwCount(); };
  $('btnReClass').onclick=()=>{
    readDictFromUI();
    if(state.mode==='ai'){ aiClassify(); } else { runClassification(); }
  };
  $('modeSeg').querySelectorAll('button').forEach(b=>{
    b.onclick=()=>{
      state.mode=b.dataset.mode;
      $('modeSeg').querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));
      if(state.mode==='ai' && !state.ai.key){ toast('已切到 AI 增强：请在设置填写 API Key 后点重新分类'); }
    };
  });
  $('search').oninput=e=>{ state.search=e.target.value; renderTable(); };
  $('colSelect').onchange=e=>{ if(state.results.length && !confirm('切换关键词列将重新分类，当前结果将丢失，是否继续？')) return; state.keywordCol=parseInt(e.target.value,10); runClassification(); };
  $('catFilter').onchange=e=>{ state.filterCat=e.target.value; state.filters.cat=''; renderLegend(); renderTable(); syncCatFilter(); };
  $('onlyHit').onchange=()=>renderLegend();
  $('btnExport').onclick=exportXLSX;

  // 表头筛选
  const FILTER_MAP={
    cat:r=>CAT_NAME[r.cat],
    intent:r=>INTENT_NAMES[r.intent]||'',
    stage:r=>STAGE_NAMES[r.stage]||'',
    dim:r=>r.dimLabel||'',
    source:r=>r.source||'离线'
  };
  const FILTER_VALUE_MAP={
    cat:(name)=>{ const c=CATEGORIES.find(c=>c.name===name); return c?c.id:name; },
    intent:(name)=>{ const entry=Object.entries(INTENT_NAMES).find(([k,v])=>v===name); return entry?entry[0]:name; },
    stage:(name)=>{ const entry=Object.entries(STAGE_NAMES).find(([k,v])=>v===name); return entry?entry[0]:name; },
    dim:(name)=>name,
    source:(name)=>name
  };
  let activeDropdown=null;
  let activeTh=null;
  function closeDropdown(){ if(activeDropdown){ activeDropdown.classList.remove('show'); activeDropdown.remove(); activeDropdown=null; activeTh=null; } }
  function repositionDropdown(){
    if(activeDropdown && activeTh){
      const rect=activeTh.getBoundingClientRect();
      activeDropdown.style.left=rect.left+'px';
      activeDropdown.style.top=rect.bottom+'px';
    }
  }
  document.querySelectorAll('.th-filter').forEach(th=>{
    th.addEventListener('click',function(e){
      e.stopPropagation();
      const key=this.dataset.filter;
      const old=this.querySelector('.filter-dropdown');
      if(old){ closeDropdown(); return; }
      closeDropdown();
      // collect unique values
      const vals=new Set();
      state.results.forEach(r=>{ const v=FILTER_MAP[key](r); if(v) vals.add(v); });
      if(!vals.size) return;
      const sorted=[...vals].sort();
      const div=document.createElement('div');
      div.className='filter-dropdown show';
      const rect=this.getBoundingClientRect();
      div.style.left=rect.left+'px';
      div.style.top=rect.bottom+'px';
      let hasItems=false;
      sorted.forEach(v=>{
        const item=document.createElement('div');
        const actualVal=FILTER_VALUE_MAP[key](v);
        item.className='fd-item'+(state.filters[key]===actualVal?' on':'');
        item.textContent=v;
        item.onclick=(ev)=>{ ev.stopPropagation(); state.filters[key]=state.filters[key]===actualVal?'':actualVal; if(key==='cat') state.filterCat=''; renderLegend(); renderTable(); closeDropdown(); };
        div.appendChild(item); hasItems=true;
      });
      const clear=document.createElement('div');
      clear.className='fd-clear'; clear.textContent='清除筛选';
      clear.onclick=(ev)=>{ ev.stopPropagation(); state.filters[key]=''; if(key==='cat') state.filterCat=''; renderLegend(); renderTable(); closeDropdown(); };
      div.appendChild(clear);
      document.body.appendChild(div);
      activeDropdown=div;
      activeTh=this;
    });
  });
  document.addEventListener('click',closeDropdown);
  $('tableWrap').addEventListener('scroll',repositionDropdown);
  window.addEventListener('scroll',repositionDropdown,true);

  // 勾选委托
  $('resultBody').addEventListener('change',e=>{
    const cb=e.target.closest('input[type=checkbox]');
    if(!cb) return;
    const idx=parseInt(cb.dataset.idx,10);
    if(cb.checked){
      state.checkedUnchecked?.delete(idx);
      if(state.checkedUnchecked && state.checkedUnchecked.size===0) state.checkedUnchecked=null;
    } else {
      if(!state.checkedUnchecked) state.checkedUnchecked=new Set();
      state.checkedUnchecked.add(idx);
    }
    $('chkAll').checked = state.checkedUnchecked===null;
  });

  $('btnSettings').onclick=()=>{ fillDictTextareas(); $('drawer').classList.add('open'); $('drawerMask').style.display='block'; };
  $('drawerClose').onclick=closeDrawer;
  $('drawerMask').onclick=closeDrawer;
  $('resetDict').onclick=()=>{ state.dict={brand:[...BASE.brand],competitor:[...BASE.competitor],product:[...BASE.product],geo:[...BASE.geo],ext:{question:[],reputation:[],promo:[],price:[],attribute:[],audience:[],company:[],phone:[],factory:[]}}; fillDictTextareas(); toast('已重置为内置词典'); if(state.results.length) runClassification(); };
  $('confTh').oninput=e=>{ const v=Math.max(0,Math.min(100,parseInt(e.target.value,10))); state.confTh=v; $('confThVal').textContent=v; clearTimeout(state._confTimer); state._confTimer=setTimeout(()=>renderTable(),50); };

  // 折叠：分类分布
  if(typeof document !== 'undefined' && typeof document.querySelectorAll === 'function'){
  document.querySelectorAll('.fold-h2').forEach(h2=>{
    const key = 'fold_' + h2.dataset.fold;
    if(localStorage.getItem(key) === '1') h2.classList.add('collapsed');
    h2.onclick = () => {
      h2.classList.toggle('collapsed');
      localStorage.setItem(key, h2.classList.contains('collapsed') ? '1' : '0');
    };
  });
  }
  // 列宽拖动调整
  let resizingCol=-1;
  let startX=0;
  let startWidth=0;
  let resizeHandle=null;
  const charWidth=measureTextWidth('中');
  const minWidth=charWidth*8;
  document.addEventListener('mousedown',e=>{
    const handle=e.target.closest('.col-resize-handle');
    if(!handle) return;
    e.preventDefault();
    resizingCol=parseInt(handle.dataset.col,10);
    startX=e.clientX;
    const th=handle.parentElement;
    startWidth=parseFloat(th.style.width)||parseFloat(th.dataset.maxWidth)||100;
    resizeHandle=handle;
    handle.classList.add('active');
    document.body.classList.add('col-resizing');
  });
  document.addEventListener('mousemove',e=>{
    if(resizingCol<0) return;
    e.preventDefault();
    const deltaX=e.clientX-startX;
    const newWidth=startWidth+deltaX;
    const tbl=$('resultTable');
    const ths=tbl.querySelectorAll('thead th');
    const th=ths[resizingCol];
    const maxWidth=parseFloat(th.dataset.maxWidth)||newWidth;
    const clampedWidth=Math.max(minWidth, Math.min(newWidth, maxWidth));
    th.style.width=clampedWidth+'px';
    if(!state.colWidths) state.colWidths={};
    state.colWidths[resizingCol]=clampedWidth;
  });
  document.addEventListener('mouseup',e=>{
    if(resizingCol<0) return;
    if(resizeHandle) resizeHandle.classList.remove('active');
    document.body.classList.remove('col-resizing');
    resizingCol=-1;
    resizeHandle=null;
  });
}
let _dictDirty=false;
function markDictDirty(){ _dictDirty=true; }
function initDictDirtyTracking(){
  const ids=['dictBrand','dictComp','dictProduct','dictGeo','extQuestion','extReputation','extPromo','extPrice','extAttribute','extAudience','extCompany','extPhone','extFactory'];
  ids.forEach(id=>{ const el=$(id); if(el) el.oninput=markDictDirty; });
}
function closeDrawer(){ $('drawer').classList.remove('open'); $('drawerMask').style.display='none'; if(_dictDirty){ readDictFromUI(); renderTable(); _dictDirty=false; } }

